 using Microsoft.ML;
 using Microsoft.ML.Data;
 using Microsoft.Extensions.ML;

 var builder = WebApplication.CreateBuilder(args);

 var mlContext = new MLContext(seed: 42);
 var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");

 // Load and split data
 var rawData = mlContext.Data.LoadFromTextFile<CustomerDataRaw>(dataPath, hasHeader: true, separatorChar: ',');

 // Map "Yes"/"No" string to boolean Label
 var allData = mlContext.Transforms.CustomMapping<CustomerDataRaw, ChurnLabel>(
     (input, output) => output.Label = string.Equals(input.Churned, "Yes", StringComparison.OrdinalIgnoreCase),
     contractName: null)
     .Fit(rawData).Transform(rawData);

 var split = mlContext.Data.TrainTestSplit(allData, testFraction: 0.2);

 // Build the training pipeline
 var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerDataRaw.Region))
     .Append(mlContext.Transforms.Concatenate("Features",
         nameof(CustomerDataRaw.Age),
         nameof(CustomerDataRaw.Income),
         "RegionEncoded",
         nameof(CustomerDataRaw.PurchaseHistory)))
     .Append(mlContext.Transforms.NormalizeMinMax("Features"))
     .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
         labelColumnName: "Label", featureColumnName: "Features"));

 // Train and evaluate
 var model = pipeline.Fit(split.TrainSet);
 var predictions = model.Transform(split.TestSet);
 var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");

 Console.WriteLine($"Accuracy: {metrics.Accuracy:F4}");
 Console.WriteLine($"AUC:      {metrics.AreaUnderRocCurve:F4}");
 Console.WriteLine($"F1 Score: {metrics.F1Score:F4}");

 // Save the trained model
 var modelPath = Path.Combine(AppContext.BaseDirectory, "churn-model.zip");
 mlContext.Model.Save(model, allData.Schema, modelPath);

 // Register a pooled prediction engine for thread-safe web usage
 builder.Services.AddPredictionEnginePool<CustomerDataRaw, ChurnPrediction>()
     .FromFile(modelPath);

 var app = builder.Build();

 app.MapPost("/predict", (PredictionEnginePool<CustomerDataRaw, ChurnPrediction> pool, CustomerRequest req) =>
 {
     var input = new CustomerDataRaw
     {
         Age = req.Age,
         Income = req.Income,
         Region = req.Region,
         PurchaseHistory = req.PurchaseHistory,
         Churned = "No"
     };
     var prediction = pool.Predict(input);
     return Results.Ok(new
     {
         WillChurn = prediction.PredictedLabel,
         Probability = prediction.Probability
     });
 });

 app.Run();

 // --- Data models ---

 public class CustomerDataRaw
 {
     [LoadColumn(0)] public float Age { get; set; }
     [LoadColumn(1)] public float Income { get; set; }
     [LoadColumn(2)] public string Region { get; set; } = string.Empty;
     [LoadColumn(3)] public float PurchaseHistory { get; set; }
     [LoadColumn(4)] public string Churned { get; set; } = string.Empty;
 }

 public class ChurnLabel
 {
     public bool Label { get; set; }
 }

 public class ChurnPrediction
 {
     [ColumnName("PredictedLabel")]
     public bool PredictedLabel { get; set; }
     public float Probability { get; set; }
 }

 public record CustomerRequest(float Age, float Income, string Region, float PurchaseHistory);

